using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Eval;

/// <summary>
/// Shared evaluation infrastructure for telemetry, quality, and compare modes.
/// </summary>
internal static class EvalSetup
{
    private static readonly string ResultsDir =
        Path.Combine(AppContext.BaseDirectory, "eval-results");

    /// <summary>
    /// Creates a <see cref="ReportingConfiguration"/> wired for telemetry capture,
    /// quality evaluators, and disk-based result storage (enables compare across runs).
    /// </summary>
    public static ReportingConfiguration CreateReportingConfig(IChatClient judge)
    {
        // Quality evaluators
        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        // Disk storage allows compare mode: diff successive runs in the same directory.
        var storage = new DiskBasedResultStore(ResultsDir);

        return new ReportingConfiguration(
            chatClient: judge,
            evaluators: evaluators,
            resultStore: storage,
            enableResponseCaching: true);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

[TestClass]
public sealed class QualityTests
{
    private static ReportingConfiguration? s_config;

    [ClassInitialize]
    public static void Init(TestContext _)
    {
        // The judge model evaluates the target model's responses.
        var judge = new ChatClientBuilder()
            .UseChatClient(new AzureOpenAIChatClient("chat", "gpt-4o-mini"));

        s_config = EvalSetup.CreateReportingConfig(judge);
    }

    [TestMethod]
    public async Task Coach_Responds_With_Relevant_Answer()
    {
        await using var session = await s_config!.CreateSessionAsync(
            scenarioName: nameof(Coach_Responds_With_Relevant_Answer));

        // Arrange – build a target chat client (the system under test).
        var target = new ChatClientBuilder()
            .UseChatClient(new AzureOpenAIChatClient("chat", "gpt-4o-mini"));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What are three benefits of unit testing?")
        };

        // Act – get a response from the target model.
        var response = await target.GetResponseAsync(messages);

        // Evaluate – run quality evaluators and record telemetry.
        await session.EvaluateAsync(messages, response);

        // Assert – all metric scores should be acceptable.
        foreach (var metric in session.GetMetrics())
        {
            if (metric is NumericMetric numeric)
            {
                Assert.IsTrue(
                    numeric.Value >= 3,
                    $"{metric.Name} scored {numeric.Value}, expected >= 3");
            }
        }
    }

    [TestMethod]
    public async Task Coach_Handles_Ambiguous_Query()
    {
        await using var session = await s_config!.CreateSessionAsync(
            scenarioName: nameof(Coach_Handles_Ambiguous_Query));

        var target = new ChatClientBuilder()
            .UseChatClient(new AzureOpenAIChatClient("chat", "gpt-4o-mini"));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain it better")
        };

        var response = await target.GetResponseAsync(messages);

        await session.EvaluateAsync(messages, response);

        foreach (var metric in session.GetMetrics())
        {
            if (metric is NumericMetric numeric)
            {
                // Ambiguous input – we mainly confirm no crash; lower threshold.
                Assert.IsTrue(
                    numeric.Value >= 1,
                    $"{metric.Name} scored {numeric.Value}, expected >= 1");
            }
        }
    }
}

using System.Diagnostics;
using Microsoft.Extensions.AI;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Validates that OpenTelemetry spans are emitted by the chat pipeline.
/// This ensures the telemetry wiring is functional without requiring an external collector.
/// </summary>
[TestClass]
public sealed class TelemetryTests
{
    [TestMethod]
    public async Task ChatClient_Emits_Activity_Spans()
    {
        var captured = new List<Activity>();

        using var listener = new ActivityListener
        {
            ShouldListenTo = source => source.Name.Contains("Microsoft.Extensions.AI"),
            Sample = (ref ActivityCreationOptions<ActivityContext> _) =>
                ActivitySamplingResult.AllDataAndRecorded,
            ActivityStopped = activity => captured.Add(activity)
        };
        ActivitySource.AddActivityListener(listener);

        var client = new ChatClientBuilder()
            .UseChatClient(new AzureOpenAIChatClient("chat", "gpt-4o-mini"));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello")
        };

        await client.GetResponseAsync(messages);

        Assert.IsTrue(
            captured.Count > 0,
            "Expected at least one Activity span from the chat pipeline.");
    }
}

