public sealed class TelemetryTests
{
    [TestMethod]
    public async Task ChatClient_Emits_Activity_Spans()
    {
        var captured = new List<Activity>();

        using var listener = new ActivityListener
        {
            ShouldListenTo = source => source.Name.Contains("Microsoft.Extensions.AI"),
            Sample = (ref ActivityCreationOptions<ActivityContext> _) =>
                ActivitySamplingResult.AllDataAndRecorded,
            ActivityStopped = activity => captured.Add(activity)
        };
        ActivitySource.AddActivityListener(listener);

        var client = new ChatClientBuilder()
            .UseChatClient(new AzureOpenAIChatClient("chat", "gpt-4o-mini"));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello")
        };

        await client.GetResponseAsync(messages);

        Assert.IsTrue(
            captured.Count > 0,
            "Expected at least one Activity span from the chat pipeline.");
    }
}

