using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Demonstrates compare mode: run this test multiple times to accumulate results
/// in the disk-based store, then use the reporting tool to diff between runs.
/// </summary>
[TestClass]
public sealed class CompareTests
{
    private static ReportingConfiguration? s_config;

    [ClassInitialize]
    public static void Init(TestContext _)
    {
        var judge = new ChatClientBuilder()
            .UseChatClient(new AzureOpenAIChatClient("chat", "gpt-4o-mini"));

        s_config = EvalSetup.CreateReportingConfig(judge);
    }

    [TestMethod]
    public async Task Baseline_Scenario_For_Comparison()
    {
        // Each run is stored with a timestamp, enabling side-by-side comparison.
        await using var session = await s_config!.CreateSessionAsync(
            scenarioName: nameof(Baseline_Scenario_For_Comparison));

        var target = new ChatClientBuilder()
            .UseChatClient(new AzureOpenAIChatClient("chat", "gpt-4o-mini"));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Summarize the benefits of continuous integration in two sentences.")
        };

        var response = await target.GetResponseAsync(messages);

        await session.EvaluateAsync(messages, response);

        // No hard assertion – compare mode relies on viewing diffs across runs.
        var metrics = session.GetMetrics();
        Assert.IsTrue(metrics.Any(), "Expected at least one metric to be recorded.");
    }
}

